def lattice(g, hlines, vlines):
    return [[g[r][c] for c in vlines] for r in hlines]
d2=G['Demo pair 2 input']
L2=lattice(d2,[0,5,10,15,20,25],[1,5,9,13,17,21,25])
for r in L2: print(r)
def solve(L, fill):
    R,C=len(L),len(L[0])
    cells={}
    for i in range(R-1):
        for j in range(C-1):
            s={L[i][j],L[i][j+1],L[i+1][j],L[i+1][j+1]}
            if len(s)==1:
                cells[(i,j)]=next(iter(s))
    if not cells: return None
    rs=[k[0] for k in cells]; cs=[k[1] for k in cells]
    out=[[fill]*(max(cs)-min(cs)+1) for _ in range(max(rs)-min(rs)+1)]
    for (i,j),c in cells.items(): out[i-min(rs)][j-min(cs)]=c
    return out
